// Runs every media recipe against the real FFmpeg WebAssembly core that the site
// ships (node_modules/@ffmpeg/core), with disk-backed outputs through the same
// output file system the browser worker uses. Run: node tests/media-engine.mjs [group]
// Groups: video, audio, gif (npm run test:media runs each in its own process).
// Fixtures are generated by FFmpeg itself.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { FFmpegHost } from '../src/scripts/media/ffmpeg-host.mjs';
import { createContext } from '../src/scripts/media/recipe-context.mjs';
import { recipes } from '../src/scripts/media/recipes.mjs';
import { mediaTools, defaults } from '../src/scripts/media/media-tools.mjs';
import { mediaInfo } from '../src/scripts/media/probe.mjs';

globalThis.self = globalThis;
globalThis.location ||= { href: 'file:///ffmpeg-core.js' };
const coreDir = 'node_modules/@ffmpeg/core/dist/esm';
const wasm = await WebAssembly.compile(fs.readFileSync(`${coreDir}/ffmpeg-core.wasm`));
let generation = 0;
async function newHost() {
  const { default: create } = await import(`../${coreDir}/ffmpeg-core.js?v=${++generation}`);
  const core = await create({
    mainScriptUrlOrBlob: `x.js#${btoa(JSON.stringify({ wasmURL: 'x', workerURL: '' }))}`,
    instantiateWasm(imports, done) {
      WebAssembly.instantiate(wasm, imports).then((i) => done(i, wasm));
      return {};
    },
  });
  return new FFmpegHost(core, { workerfs: false });
}

// Disk handle with the FileSystemSyncAccessHandle methods OUTFS uses.
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ks-media-'));
class FdHandle {
  constructor(file) { this.file = file; this.fd = fs.openSync(file, 'w+'); }
  read(view, { at }) { return fs.readSync(this.fd, view, 0, view.byteLength, at); }
  write(view, { at }) { return fs.writeSync(this.fd, view, 0, view.byteLength, at); }
  getSize() { return fs.fstatSync(this.fd).size; }
  truncate(n) { fs.ftruncateSync(this.fd, n); }
  flush() {}
  close() { fs.closeSync(this.fd); }
}

let host = await newHost();
async function run(id, inputs, options = {}) {
  // Like the browser worker, the engine is reused between jobs. The worker is
  // recycled after a crash or a dozen jobs; here each group runs in its own process.
  if (host.dead) host = await newHost();
  host.clear();
  host.mountInputs(inputs.map((i) => ({ name: i.name, data: i.data })));
  const infos = inputs.map((i) => ({ name: i.name, info: mediaInfo(host.probe(`/in/${i.name}`)) }));
  const handles = new Map();
  const backend = {
    async exec(args, outputs, onTime) {
      for (const name of outputs) {
        const h = new FdHandle(path.join(tmp, `${id}-${name}`));
        handles.set(name, h);
        host.announce(name, h);
      }
      host.onTime = onTime;
      const result = host.exec(args);
      host.onTime = null;
      if (result.crashed) throw new Error(`engine crashed: ${result.log.split('\n').slice(-4).join(' | ')}`);
      return result;
    },
    async write(p, data) { host.write(p, data); },
    async asset(p) { return new Uint8Array(fs.readFileSync(`public/${p}`)); },
    async remove(names) { for (const n of names) { host.remove(n); handles.get(n)?.close(); handles.delete(n); } },
    async list() { return host.files().map((f) => f.name); },
    async collect(names, opts = {}) {
      const out = [];
      const { createCanvas, loadImage } = opts.jpeg ? await import('@napi-rs/canvas') : {};
      for (const f of host.files().filter((f) => names.includes(f.name))) {
        let data;
        if (handles.has(f.name)) {
          const h = handles.get(f.name); h.close(); handles.delete(f.name);
          data = fs.readFileSync(h.file);
        } else data = Buffer.from(f.data);
        host.remove(f.name);
        if (opts.jpeg) {
          // Same step as the browser: PNG from FFmpeg, JPG from an image encoder.
          const image = await loadImage(data);
          const canvas = createCanvas(image.width, image.height);
          canvas.getContext('2d').drawImage(image, 0, 0);
          out.push({ name: f.name.replace(/\.png$/i, '.jpg'), data: canvas.toBuffer('image/jpeg', 92) });
          continue;
        }
        out.push({ name: f.name, data });
      }
      return out;
    },
  };
  let last = 0;
  const ctx = createContext(backend, { inputs: infos, onProgress: (r) => { assert.ok(r >= last - 1e-9 && r <= 1 + 1e-9, `${id}: progress ${r} after ${last}`); last = r; } });
  const result = await recipes[id](ctx, { ...defaults(id), ...options });
  for (const h of handles.values()) h.close();
  return result;
}
async function probe(file) {
  if (host.dead) host = await newHost();
  host.clear();
  host.mountInputs([{ name: file.name, data: file.data }]);
  const info = mediaInfo(host.probe(`/in/${file.name}`));
  host.clear();
  return info;
}
async function make(name, args) {
  if (host.dead) host = await newHost();
  host.clear();
  const r = host.exec([...args, `/work/${name}`]);
  assert.equal(r.ret, 0, `fixture ${name}: ${r.log.slice(-300)}`);
  const data = host.FS.readFile(`/work/${name}`);
  host.clear();
  return { name, data };
}

const near = (a, b, tolerance, label) => assert.ok(Math.abs(a - b) <= tolerance, `${label}: ${a} is not within ${tolerance} of ${b}`);
const only = process.argv[2] || 'video';
const t0 = Date.now();
const passed = [];
async function check(id, inputs, options, verify) {
  if (only !== 'all' && mediaTools[id].kind !== only && !(only === 'video' && mediaTools[id].kind === 'video')) return;
  const start = Date.now();
  const outputs = await run(id, inputs, options);
  assert.ok(outputs.length > 0, `${id}: no output`);
  for (const o of outputs) assert.ok(o.data.length > 0, `${id}: empty ${o.name}`);
  await verify(outputs);
  passed.push(`${id} ${Date.now() - start}ms`);
}

// ---------------------------------------------------------------- fixtures
const video = await make('clip.mp4', ['-f', 'lavfi', '-i', 'testsrc2=size=320x180:rate=25:duration=4', '-f', 'lavfi', '-i', 'sine=frequency=440:duration=4', '-c:v', 'libx264', '-preset', 'ultrafast', '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-shortest']);
const video2 = await make('second.mov', ['-f', 'lavfi', '-i', 'testsrc=size=480x360:rate=30:duration=2', '-c:v', 'libx264', '-preset', 'ultrafast', '-pix_fmt', 'yuv420p']);
const subtitles = await make('subs.srt', ['-f', 'lavfi', '-i', 'anullsrc', '-t', '0', '-f', 'srt', '-y']).catch(() => null);
const srt = { name: 'talk.srt', data: Buffer.from('1\n00:00:00,500 --> 00:00:02,000\nHello Loki\n\n2\n00:00:02,500 --> 00:00:03,500\nSecond line\n') };
host.clear();
host.mountInputs([{ name: 'clip.mp4', data: video.data }, { name: 'talk.srt', data: srt.data }]);
host.exec(['-i', '/in/clip.mp4', '-i', '/in/talk.srt', '-map', '0', '-map', '1', '-c', 'copy', '-c:s', 'srt', '/work/subbed.mkv']);
const subbed = { name: 'subbed.mkv', data: host.FS.readFile('/work/subbed.mkv') };
host.clear();
const speech = await make('speech.wav', ['-f', 'lavfi', '-i', 'anullsrc=r=44100:cl=stereo:d=1', '-f', 'lavfi', '-i', 'sine=frequency=300:duration=2:sample_rate=44100', '-f', 'lavfi', '-i', 'anullsrc=r=44100:cl=stereo:d=2', '-f', 'lavfi', '-i', 'sine=frequency=500:duration=2:sample_rate=44100', '-f', 'lavfi', '-i', 'anullsrc=r=44100:cl=stereo:d=1', '-filter_complex', '[1:a]aformat=channel_layouts=stereo[b];[3:a]aformat=channel_layouts=stereo[d];[0:a][b][2:a][d][4:a]concat=n=5:v=0:a=1[a]', '-map', '[a]']);
const song = await make('song.mp3', ['-f', 'lavfi', '-i', 'sine=frequency=220:duration=3', '-ac', '2', '-c:a', 'libmp3lame']);
const gif = await make('loop.gif', ['-f', 'lavfi', '-i', 'testsrc2=size=200x120:rate=10:duration=2']);
const png1 = await make('one.png', ['-f', 'lavfi', '-i', 'color=c=teal:size=300x200', '-frames:v', '1']);
const png2 = await make('two.png', ['-f', 'lavfi', '-i', 'color=c=orange:size=200x300', '-frames:v', '1']);
const logo = await make('logo.png', ['-f', 'lavfi', '-i', 'color=c=white:size=64x32', '-frames:v', '1']);
void subtitles;

// ---------------------------------------------------------------- video
await check('video-converter', [video], { format: 'mkv' }, async ([o]) => {
  const info = await probe(o); assert.equal(info.video.codec, 'h264'); assert.match(o.name, /\.mkv$/); near(info.duration, 4, 0.2, 'remux duration');
});
await check('video-converter', [video], { format: 'webm' }, async ([o]) => {
  const info = await probe(o); assert.equal(info.video.codec, 'vp8'); assert.equal(info.audio.codec, 'opus');
});
await check('video-converter', [video], { format: 'avi' }, async ([o]) => assert.equal((await probe(o)).video.codec, 'mpeg4'));
await check('video-converter', [video2], { format: 'mp4' }, async ([o]) => assert.equal((await probe(o)).video.width, 480));
await check('compress-video', [video], { quality: 'small', height: '360' }, async ([o]) => assert.ok(o.data.length < video.data.length * 1.5));
await check('compress-video', [video], { target: '0.2' }, async ([o]) => assert.ok(o.data.length < 0.2 * 1048576 * 1.25, `target size: ${o.data.length}`));
await assert.rejects(() => run('compress-video', [video], { target: '0.001' }), /too small/);
await check('trim-video', [video], { start: 1, end: 3 }, async ([o]) => near((await probe(o)).duration, 2, 0.15, 'exact trim'));
await check('trim-video', [video], { start: 1, end: 3, mode: 'fast' }, async ([o]) => assert.ok((await probe(o)).duration <= 3.1));
await assert.rejects(() => run('trim-video', [video], { start: 3, end: 2 }), /end must be after/);
await check('mute-video', [video], {}, async ([o]) => assert.equal((await probe(o)).audio, undefined));
await check('resize-video', [video], { size: '360' }, async ([o]) => assert.equal((await probe(o)).video.height, 360));
await check('resize-video', [video], { size: 'custom', width: 200, height: 200 }, async ([o]) => { const v = (await probe(o)).video; assert.equal(v.width, 200); assert.equal(v.height, 200); });
await check('crop-video', [video], { ratio: '9:16' }, async ([o]) => { const v = (await probe(o)).video; near(v.width / v.height, 9 / 16, 0.03, 'crop ratio'); });
await check('rotate-video', [video], { turn: 'cw' }, async ([o]) => { const v = (await probe(o)).video; assert.equal(v.width, 180); assert.equal(v.height, 320); });
await check('change-speed', [video], { speed: '2' }, async ([o]) => near((await probe(o)).duration, 2, 0.2, 'speed 2x'));
await check('change-speed', [song], { speed: '0.5' }, async ([o]) => { assert.match(o.name, /\.mp3$/); near((await probe(o)).duration, 6, 0.3, 'audio 0.5x'); });
await check('reverse-video', [video], {}, async ([o]) => near((await probe(o)).duration, 4, 0.3, 'reverse'));
await check('boomerang-video', [video], { start: 0.5, length: 1, loops: '2' }, async ([o]) => near((await probe(o)).duration, 4, 0.3, 'boomerang'));
await check('extract-audio', [video], { format: 'mp3' }, async ([o]) => assert.equal((await probe(o)).audio.codec, 'mp3'));
await check('extract-audio', [video], { format: 'original' }, async ([o]) => { assert.match(o.name, /\.m4a$/); assert.equal((await probe(o)).audio.codec, 'aac'); });
await assert.rejects(() => run('extract-audio', [video2], {}), /no audio track/);
await check('video-to-images', [video], { every: '1' }, async (frames) => { assert.ok(frames.length >= 4 && frames.length <= 5, `frames: ${frames.length}`); assert.match(frames[0].name, /clip-00001\.jpg$/); });
await check('join-videos', [video, video2], {}, async ([o]) => { const info = await probe(o); near(info.duration, 6, 0.4, 'join'); assert.equal(info.video.width, 320); assert.ok(info.audio); });
await check('join-videos', [video, video], {}, async ([o]) => near((await probe(o)).duration, 8, 0.3, 'join copy'));
await check('replace-audio', [video2, song], {}, async ([o]) => { const info = await probe(o); assert.ok(info.audio); near(info.duration, 2, 0.2, 'replace length'); });
await check('replace-audio', [video, song], { mode: 'mix' }, async ([o]) => assert.ok((await probe(o)).audio));
await check('split-video', [video], { by: 'parts', parts: 2, mode: 'exact' }, async (parts) => { assert.equal(parts.length, 2); near((await probe(parts[1])).duration, 2, 0.2, 'split part'); });
await check('split-video', [video], { by: 'seconds', seconds: 3 }, async (parts) => assert.equal(parts.length, 2));
await check('extract-subtitles', [subbed], { format: 'vtt' }, async ([o]) => assert.match(Buffer.from(o.data).toString(), /WEBVTT[\s\S]*Hello Loki/));
await assert.rejects(() => run('extract-subtitles', [video], {}), /no subtitle tracks/);
await check('subtitle-converter', [srt], { format: 'vtt', offset: 1 }, async ([o]) => assert.match(Buffer.from(o.data).toString(), /00:01\.500 --> 00:03\.000/));
await check('video-contact-sheet', [video], { grid: '3x3', width: '160' }, async ([o]) => { assert.match(o.name, /-contact-sheet\.jpg$/); const v = (await probe(o)).video; assert.ok(v.width > 160 * 3, `sheet width ${v.width}`); });
await check('repair-video', [video], {}, async ([o]) => near((await probe(o)).duration, 4, 0.2, 'repair'));
await check('burn-subtitles', [video, srt], {}, async ([o]) => {
  assert.match(o.name, /-subtitled\.mp4$/);
  // The text must really be drawn: the bottom of a frame differs from the original.
  const frame = (data) => {
    host.clear();
    host.mountInputs([{ name: 'f.mp4', data }]);
    host.exec(['-ss', '1', '-i', '/in/f.mp4', '-frames:v', '1', '-f', 'rawvideo', '-pix_fmt', 'gray', '/work/f.raw']);
    return host.FS.readFile('/work/f.raw');
  };
  const a = frame(o.data);
  const b = frame(video.data);
  let changed = 0;
  for (let i = a.length - 320 * 60; i < a.length; i++) if (Math.abs(a[i] - b[i]) > 60) changed++;
  assert.ok(changed > 80, `subtitles not visible (${changed} changed pixels)`);
});
await check('burn-subtitles', [video, srt], { position: 'top', size: 'large' }, async ([o]) => {
  const frame = (data) => {
    host.clear();
    host.mountInputs([{ name: 'f.mp4', data }]);
    host.exec(['-ss', '1', '-i', '/in/f.mp4', '-frames:v', '1', '-f', 'rawvideo', '-pix_fmt', 'gray', '/work/f.raw']);
    return host.FS.readFile('/work/f.raw');
  };
  const a = frame(o.data);
  const b = frame(video.data);
  // Text in the top band, centred horizontally, and nothing added at the bottom.
  let top = 0, left = 0, bottom = 0;
  for (let y = 0; y < 60; y++) for (let x = 0; x < 320; x++) {
    const i = y * 320 + x;
    if (Math.abs(a[i] - b[i]) > 60) { top++; if (x < 80) left++; }
  }
  for (let i = a.length - 320 * 40; i < a.length; i++) if (Math.abs(a[i] - b[i]) > 60) bottom++;
  assert.ok(top > 80 && left < top / 4 && bottom < 20, `top subtitles misplaced (top ${top}, left ${left}, bottom ${bottom})`);
});
await check('watermark-video', [video, logo], { position: 'top-left' }, async ([o]) => assert.equal((await probe(o)).video.width, 320));
