for (const format of ['mp3', 'm4a', 'wav', 'ogg', 'opus', 'flac', 'aiff'])
  await check('audio-converter', [speech], { format }, async ([o]) => { assert.ok(o.name.endsWith(`.${format}`)); near((await probe(o)).duration, 8, 0.2, `to ${format}`); });
