await check('normalize-audio', [song], { target: '-16' }, async ([o]) => near((await probe(o)).duration, 3, 0.15, 'normalize'));
await check('remove-silence', [speech], { where: 'edges', threshold: '-40' }, async ([o]) => near((await probe(o)).duration, 6, 0.3, 'trim silence at edges'));
await check('remove-silence', [speech], { where: 'all', threshold: '-40', pause: 0.5 }, async ([o]) => assert.ok((await probe(o)).duration < 5.5, 'pauses removed'));
